using System.Net;
using System.Net.Http.Json;
using System.Text;
using System.Text.Json;
using Marketplace.Api.Data;
using Marketplace.Api.Identity;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Identity;
using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.AspNetCore.WebUtilities;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Infrastructure;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.DependencyInjection.Extensions;
using Xunit;
namespace Marketplace.Api.Tests;

public sealed class AuthTests
{
    private sealed class Factory : WebApplicationFactory<Program> { public readonly SqliteConnection Connection = new("Data Source=:memory:"); protected override void ConfigureWebHost(IWebHostBuilder builder) { builder.UseEnvironment("Testing"); Connection.Open(); builder.ConfigureServices(services => { services.RemoveAll<DbContextOptions<MarketplaceDbContext>>(); services.RemoveAll<IDbContextOptionsConfiguration<MarketplaceDbContext>>(); services.AddDbContext<MarketplaceDbContext>(o => o.UseSqlite(Connection)); }); } public HttpClient Browser() { var client = CreateClient(new WebApplicationFactoryClientOptions { BaseAddress = new Uri("http://localhost"), HandleCookies = true }); using var scope = Services.CreateScope(); scope.ServiceProvider.GetRequiredService<MarketplaceDbContext>().Database.EnsureCreated(); return client; } }
    private static async Task<HttpResponseMessage> Post(HttpClient client, string path, object payload) { var csrf = await client.GetFromJsonAsync<JsonElement>("/api/v1/auth/csrf"); using var request = new HttpRequestMessage(HttpMethod.Post, "/api/v1/auth/" + path) { Content = JsonContent.Create(payload) }; request.Headers.Add("X-CSRF-Token", csrf.GetProperty("token").GetString()); return await client.SendAsync(request); }
    private static object Registration() => new { name = "Demo Provider", email = "provider@example.test", password = "StrongPassword!123", accountType = "Provider" };
    [Fact] public async Task RegistrationQueuesPrivateEmailAndPreventsDuplicates() { await using var factory = new Factory(); using var client = factory.Browser(); Assert.Equal(HttpStatusCode.Accepted, (await Post(client, "register", Registration())).StatusCode); Assert.Equal(HttpStatusCode.Accepted, (await Post(client, "register", Registration())).StatusCode); using var scope = factory.Services.CreateScope(); var db = scope.ServiceProvider.GetRequiredService<MarketplaceDbContext>(); Assert.Equal(1, await db.Users.CountAsync()); Assert.Equal(1, await db.VerificationEmails.CountAsync()); Assert.DoesNotContain("verify-email", (await db.VerificationEmails.SingleAsync()).ProtectedBody); Assert.NotEqual("StrongPassword!123", (await db.Users.SingleAsync()).PasswordHash); }
    [Fact] public async Task RegistrationRejectsAdminAndExtraFields() { await using var factory = new Factory(); using var client = factory.Browser(); Assert.Equal(HttpStatusCode.BadRequest, (await Post(client, "register", new { name = "Admin", email = "a@example.test", password = "StrongPassword!123", accountType = "Administrator" })).StatusCode); Assert.Equal(HttpStatusCode.BadRequest, (await Post(client, "register", new { name = "Admin", email = "a@example.test", password = "StrongPassword!123", accountType = "Provider", roles = new[] { "Administrator" } })).StatusCode); }
    [Fact] public async Task CsrfAndAuthenticationAreRequired() { await using var factory = new Factory(); using var client = factory.Browser(); Assert.Equal(HttpStatusCode.BadRequest, (await client.PostAsJsonAsync("/api/v1/auth/register", Registration())).StatusCode); Assert.Equal(HttpStatusCode.Unauthorized, (await client.GetAsync("/api/v1/users/me")).StatusCode); }
    [Fact] public async Task VerificationTokenIsSingleUse() { await using var factory = new Factory(); using var client = factory.Browser(); await Post(client, "register", Registration()); using var scope = factory.Services.CreateScope(); var users = scope.ServiceProvider.GetRequiredService<UserManager<Account>>(); var user = (await users.FindByEmailAsync("provider@example.test"))!; var token = WebEncoders.Base64UrlEncode(Encoding.UTF8.GetBytes(await users.GenerateEmailConfirmationTokenAsync(user))); Assert.Equal(HttpStatusCode.BadRequest, (await Post(client, "verify-email", new { userId = user.Id, token = "invalid" })).StatusCode); Assert.Equal(HttpStatusCode.NoContent, (await Post(client, "verify-email", new { userId = user.Id, token })).StatusCode); Assert.Equal(HttpStatusCode.BadRequest, (await Post(client, "verify-email", new { userId = user.Id, token })).StatusCode); }
    [Fact] public async Task LoginUsesHttpOnlyCookieAndLogoutRejectsReplay() { await using var factory = new Factory(); using var client = factory.Browser(); await Post(client, "register", Registration()); Assert.Equal(HttpStatusCode.Unauthorized, (await Post(client, "login", new { email = "provider@example.test", password = "WrongPassword!123" })).StatusCode); var login = await Post(client, "login", new { email = "provider@example.test", password = "StrongPassword!123" }); Assert.Equal(HttpStatusCode.OK, login.StatusCode); var cookie = login.Headers.GetValues("Set-Cookie").Single(x => x.StartsWith("marketplace_session=")); Assert.Contains("httponly", cookie.ToLowerInvariant()); Assert.Equal(HttpStatusCode.OK, (await client.GetAsync("/api/v1/users/me")).StatusCode); Assert.Equal(HttpStatusCode.NoContent, (await Post(client, "logout", new { })).StatusCode); using var replay = factory.CreateClient(new WebApplicationFactoryClientOptions { HandleCookies = false }); replay.DefaultRequestHeaders.Add("Cookie", cookie.Split(';')[0]); Assert.Equal(HttpStatusCode.Unauthorized, (await replay.GetAsync("/api/v1/users/me")).StatusCode); }
    [Fact] public async Task ExpiredSessionIsRejected() { await using var factory = new Factory(); using var client = factory.Browser(); await Post(client, "register", Registration()); await Post(client, "login", new { email = "provider@example.test", password = "StrongPassword!123" }); using (var scope = factory.Services.CreateScope()) { var db = scope.ServiceProvider.GetRequiredService<MarketplaceDbContext>(); var session = await db.AccountSessions.SingleAsync(); session.ExpiresAt = DateTime.UtcNow.AddMinutes(-1); await db.SaveChangesAsync(); } Assert.Equal(HttpStatusCode.Unauthorized, (await client.GetAsync("/api/v1/users/me")).StatusCode); }
    [Fact] public async Task RepeatedFailedPasswordsLockAccount() { await using var factory = new Factory(); using var client = factory.Browser(); await Post(client, "register", Registration()); for (var i = 0; i < 5; i++) Assert.Equal(HttpStatusCode.Unauthorized, (await Post(client, "login", new { email = "provider@example.test", password = "WrongPassword!123" })).StatusCode); Assert.Equal(HttpStatusCode.Unauthorized, (await Post(client, "login", new { email = "provider@example.test", password = "StrongPassword!123" })).StatusCode); }
    [Fact] public async Task AuthenticationRateLimitReturnsRetryAfter() { await using var factory = new Factory(); using var client = factory.Browser(); for (var i = 0; i < 20; i++) Assert.Equal(HttpStatusCode.OK, (await client.GetAsync("/api/v1/auth/csrf")).StatusCode); var limited = await client.GetAsync("/api/v1/auth/csrf"); Assert.Equal(HttpStatusCode.TooManyRequests, limited.StatusCode); Assert.True(limited.Headers.Contains("Retry-After")); }
    [Fact] public async Task ExpiredVerificationTokenIsRejected() { await using var factory = new Factory(); using var client = factory.Browser(); await Post(client, "register", Registration()); using var scope = factory.Services.CreateScope(); var options = scope.ServiceProvider.GetRequiredService<Microsoft.Extensions.Options.IOptions<DataProtectionTokenProviderOptions>>(); options.Value.TokenLifespan = TimeSpan.FromMinutes(-1); var users = scope.ServiceProvider.GetRequiredService<UserManager<Account>>(); var user = (await users.FindByEmailAsync("provider@example.test"))!; var token = WebEncoders.Base64UrlEncode(Encoding.UTF8.GetBytes(await users.GenerateEmailConfirmationTokenAsync(user))); Assert.Equal(HttpStatusCode.BadRequest, (await Post(client, "verify-email", new { userId = user.Id, token })).StatusCode); }
}
